mapper.select:
      	select t1.*
		from yh_user_file as t1
		left join yh_user_folder t2
		on t1.file_parent_folder = t2.folder_id
		where t1.user_code=#{userCode,jdbcType=VARCHAR}
		and file_parent_folder = #{fileParentFolder,jdbcType=VARCHAR}
		 order by file_create_date desc limit #{page},#{pageSize}
